/** Relative path -> contents. */
type Files = Map<string, string | Uint8Array>;

// --- JSON in the editors' layout -------------------------------------------------
//
// The editors write object keys in alphabetical order, database files one
// record per line, and maps with `data` and `events` last (events one per
// line). Sorting keys here keeps every run byte-identical.

function sortKeys(v: unknown): unknown {
  if (Array.isArray(v)) return v.map(sortKeys);
  if (v !== null && typeof v === "object") {
    const out: Record<string, unknown> = {};
    for (const k of Object.keys(v).sort()) out[k] = sortKeys((v as Record<string, unknown>)[k]);
    return out;
  }
  return v;
}

const j = (v: unknown): string => JSON.stringify(sortKeys(v));

const recordsJson = (records: readonly unknown[]): string => `[\n${records.map(j).join(",\n")}\n]`;

function mapJson(map: RmMap): string {
  const { data, events, ...header } = map;
  const head = j(header);
  return `${head.slice(0, -1)},\n"data":${j(data)},\n"events":${recordsJson(events)}\n}`;
}

// --- event commands ---------------------------------------------------------------

const cmd = (code: number, ...parameters: unknown[]): RmCommand => ({ code, indent: 0, parameters });

type Part = RmCommand | readonly RmCommand[];

const seq = (...parts: Part[]): RmCommand[] => parts.flatMap((p) => (Array.isArray(p) ? p : [p as RmCommand]));

/** A command list: the parts plus the closing end-of-list command. */
const list = (...parts: Part[]): RmCommand[] => [...seq(...parts), cmd(0)];

/** A nested body: one indent deeper, closed by its own end command. */
const nest = (...parts: Part[]): RmCommand[] => [
  ...seq(...parts).map((c) => ({ ...c, indent: c.indent + 1 })),
  { code: 0, indent: 1, parameters: [] },
];

/** Show Text. MZ adds the speaker name as the fifth parameter. */
const mzText = (speaker: string, ...lines: string[]): RmCommand[] => [
  cmd(101, "", 0, 0, 2, speaker),
  ...lines.map((l) => cmd(401, l)),
];
const mvText = (...lines: string[]): RmCommand[] => [cmd(101, "", 0, 0, 2), ...lines.map((l) => cmd(401, l))];
/** MV Show Text with a background (0 window, 1 dim, 2 transparent) and a
 *  position type (0 top, 1 middle, 2 bottom). */
const mvTextAt = (background: number, position: number, ...lines: string[]): RmCommand[] => [
  cmd(101, "", 0, background, position),
  ...lines.map((l) => cmd(401, l)),
];

/** Conditional Branch with an optional Else. */
const ifThen = (cond: unknown[], then: Part[], otherwise?: Part[]): RmCommand[] => [
  cmd(111, ...cond),
  ...nest(...then),
  ...(otherwise ? [cmd(411), ...nest(...otherwise)] : []),
  cmd(412),
];

// Conditional Branch operands.
const ifSwitch = (id: number, on = true): unknown[] => [0, id, on ? 0 : 1];
/** op: 0 ==, 1 >=, 2 <=, 3 >, 4 <, 5 != (constant operand). */
const ifVar = (id: number, op: number, value: number): unknown[] => [1, id, 0, value, op];
const ifItem = (id: number): unknown[] => [8, id];

/** Show Choices. cancelType -2 adds a When Cancel branch. */
function choices(
  labels: string[],
  cancelType: number,
  defaultType: number,
  branches: Part[][],
  cancel?: Part[],
): RmCommand[] {
  return [
    cmd(102, labels, cancelType, defaultType, 2, 0),
    ...labels.flatMap((label, i) => [cmd(402, i, label), ...nest(...branches[i]!)]),
    ...(cancel ? [cmd(403, 6, null), ...nest(...cancel)] : []),
    cmd(404),
  ];
}

const loop = (...body: Part[]): RmCommand[] => [cmd(112), ...nest(...body), cmd(413)];

/** Battle Processing with its result branches. */
function battle(troopId: number, win: Part[], escape: Part[], lose: Part[]): RmCommand[] {
  return [
    cmd(301, 0, troopId, true, true),
    cmd(601),
    ...nest(...win),
    cmd(602),
    ...nest(...escape),
    cmd(603),
    ...nest(...lose),
    cmd(604),
  ];
}

/** Shop Processing: [type, id, priceType, price] goods. */
const shop = (goods: number[][], purchaseOnly: boolean): RmCommand[] => [
  cmd(302, ...goods[0]!, purchaseOnly),
  ...goods.slice(1).map((g) => cmd(605, ...g)),
];

/** Control Variables. op 0 set, 1 add; operand 0 constant, 1 variable,
 *  2 random (min, max). */
const setVar = (id: number, value: number): RmCommand => cmd(122, id, id, 0, 0, value);
const addVar = (id: number, value: number): RmCommand => cmd(122, id, id, 1, 0, value);
const switchOn = (id: number): RmCommand => cmd(121, id, id, 0);
const switchOff = (id: number): RmCommand => cmd(121, id, id, 1);
const selfOn = (ch: string): RmCommand => cmd(123, ch, 0);

/** Transfer Player: direct designation; dir 0 keeps the facing; fade 0
 *  black, 1 white, 2 none. */
const transfer = (mapId: number, x: number, y: number, dir: number, fade: number): RmCommand =>
  cmd(201, 0, mapId, x, y, dir, fade);

const comment = (...lines: string[]): RmCommand[] => [cmd(108, lines[0]), ...lines.slice(1).map((l) => cmd(408, l))];
const script = (...lines: string[]): RmCommand[] => [cmd(355, lines[0]), ...lines.slice(1).map((l) => cmd(655, l))];

// --- movement routes ----------------------------------------------------------------

const mv = (code: number, ...parameters: unknown[]): RmMoveCommand =>
  parameters.length > 0 ? { code, indent: null, parameters } : { code, indent: null };

// Route command codes (Game_Character.ROUTE_*).
const R = {
  down: 1, left: 2, right: 3, up: 4, lowerL: 5, lowerR: 6, upperL: 7, upperR: 8,
  random: 9, toward: 10, away: 11, forward: 12, backward: 13, jump: 14, wait: 15,
  turnDown: 16, turnLeft: 17, turnRight: 18, turnUp: 19, turn90R: 20, turn90L: 21, turn180: 22,
  turnRandomLR: 23, turnRandom: 24, turnToward: 25, turnAway: 26, switchOn: 27, switchOff: 28,
  speed: 29, freq: 30, walkOn: 31, walkOff: 32, stepOn: 33, stepOff: 34, dirFixOn: 35, dirFixOff: 36,
  throughOn: 37, throughOff: 38, transparentOn: 39, transparentOff: 40, image: 41, opacity: 42,
  blend: 43, se: 44, script: 45,
} as const;

function route(moves: RmMoveCommand[], repeat: boolean, skippable: boolean, wait: boolean): RmMoveRoute {
  return { list: [...moves, { code: 0 }], repeat, skippable, wait };
}

/** Set Movement Route (characterId -1 player, 0 this event) with the 505
 *  lines the editor writes for display. */
const setRoute = (charId: number, r: RmMoveRoute): RmCommand[] => [
  cmd(205, charId, r),
  ...r.list.slice(0, -1).map((m) => cmd(505, m)),
];

