const damageNone = { critical: false, elementId: 0, formula: "0", type: 0, variance: 20 };

function item(id: number, name: string, description: string, price: number, itypeId: number, iconIndex: number): RmItem {
  return {
    animationId: 0,
    consumable: itypeId === 1,
    damage: damageNone,
    description,
    effects: itypeId === 1 ? [{ code: 11, dataId: 0, value1: 0, value2: 30 }] : [],
    hitType: 0,
    iconIndex,
    id,
    itypeId,
    name,
    note: "",
    occasion: itypeId === 1 ? 0 : 3,
    price,
    repeats: 1,
    scope: itypeId === 1 ? 7 : 0,
    speed: 0,
    successRate: 100,
    tpGain: 0,
  } as RmItem;
}

function weapon(id: number, name: string, description: string, price: number, atk: number, wtypeId: number): RmItem {
  return {
    animationId: 1,
    description,
    etypeId: 1,
    iconIndex: 96 + wtypeId,
    id,
    name,
    note: "",
    params: [0, 0, atk, 0, 0, 0, 0, 0],
    price,
    traits: [{ code: 31, dataId: 1, value: 0 }, { code: 22, dataId: 0, value: 0 }],
    wtypeId,
  } as RmItem;
}

