const S_BOSS_DOWN = 10;
const S_PEACE = 11;
const V_QUEST = 1;
const V_LUCK = 2;
const V_BONUS = 3;
const V_REWARD = 5;
const V_ESCAPES = 6;
const V_DEFEATS = 7;
const V_TICKS = 9;

// Database ids.
