function hollowMaterials() {
  const a1 = (kind: number): Material => {
    switch (kind) {
      case K.pond: return material(rgb("#3a78c8"), "waves", 100);
      case K.deep: return material(rgb("#24509a"), "waves", 101);
      case 2: return material(rgb("#3a78c8"), "speckle", 102);
      case 3: return material(rgb("#24509a"), "rock", 103);
      case K.caveWater: return material(rgb("#2a6a78"), "waves", 104);
      case K.waterfall: return material(rgb("#6ab0d8"), "streaks", 105);
      default: return hueMaterial(kind, kind % 2 === 0 ? "waves" : "streaks");
    }
  };
  const a2 = (kind: number): Material => {
    switch (kind) {
      case K.grass: return material(rgb("#5aa040"), "grass", 116);
      case K.dirt: return material(rgb("#b08850"), "speckle", 117);
      case K.tallGrass: return material(rgb("#3c8a34"), "grass", 118);
      case K.stone: return material(rgb("#9a9a90"), "checker", 119);
      case K.caveDirt: return material(rgb("#6a5a4a"), "rock", 120);
      case K.carpet: return material(rgb("#a03040"), "weave", 121);
      case K.snow: return material(rgb("#e8eef4"), "speckle", 122);
      case K.table: return material(rgb("#8a5a30"), "planks", 123);
      default: return hueMaterial(kind, "speckle");
    }
  };
  const a3 = (kind: number): Material => {
    switch (kind) {
      case K.roof: return material(rgb("#b04030"), "shingles", 148);
      case K.roofBlue: return material(rgb("#3a5aa0"), "shingles", 149);
      case K.wall: return material(rgb("#e0d0b0"), "bricks", 156);
      case K.wallStone: return material(rgb("#a0a0a0"), "bricks", 157);
      default: return hueMaterial(kind, Math.floor(kind / 8) % 2 === 0 ? "shingles" : "bricks");
    }
  };
  const a4 = (kind: number): Material => {
    switch (kind) {
      case K.houseTop: return material(rgb("#5a4030"), "planks", 180);
      case K.caveTop: return material(rgb("#4a4440"), "rock", 181);
      case K.houseSide: return material(rgb("#d8c8a0"), "weave", 188);
      case K.caveSide: return material(rgb("#6a625a"), "rock", 189);
      default: return hueMaterial(kind, Math.floor(kind / 8) % 2 === 0 ? "speckle" : "bricks");
    }
  };
  return { a1, a2, a3, a4 };
}

function hollowA5(i: number): TileDraw {
  switch (i) {
    case H5.void: return plainTile(material(rgb("#101010"), "plain", 0));
    case H5.wood: return plainTile(material(rgb("#a07040"), "planks", 201));
    case H5.caveFloor: return plainTile(material(rgb("#5a524a"), "rock", 202));
    case H5.doormat: return plainTile(material(rgb("#7a3a2a"), "weave", 203));
    case H5.counter: return (c, x0, y0) => {
      const m = material(rgb("#8a5a30"), "planks", 204);
      c.paint(x0, y0, TS, TS, (x, y) => texel(m, x, y));
      c.rect(x0, y0, TS, 4, m.light);
      c.rect(x0, y0 + 4, TS, 1, m.edge);
      c.rect(x0, y0 + TS - 1, TS, 1, m.edge);
    };
    case H5.stone: return plainTile(material(rgb("#8a8a84"), "checker", 205));
    case H5.rug: return plainTile(material(rgb("#3a5a9a"), "weave", 206));
    case H5.darkCave: return plainTile(material(rgb("#3a342e"), "rock", 207));
    default: return plainTile(hueMaterial(i + 200, "checker"));
  }
}

function hollowB(): Map<number, TileDraw> {
  const leaf = rgb("#2f7a2a");
  const leafDark = shade(leaf, 0.6);
  const bark = rgb("#6a4424");
  const stone = material(rgb("#8a8680"), "rock", 300);
  const wood = material(rgb("#9a6a3a"), "planks", 301);
  const t = new Map<number, TileDraw>();
  t.set(HB.treeTop, (c, x, y) => {
    c.rect(x + 3, y + 3, 10, 13, leafDark);
    c.rect(x + 2, y + 5, 12, 11, leafDark);
    c.rect(x + 4, y + 4, 8, 12, leaf);
    c.rect(x + 3, y + 6, 10, 10, leaf);
    c.rect(x + 5, y + 6, 2, 2, shade(leaf, 1.4));
  });
  t.set(HB.treeTrunk, (c, x, y) => {
    c.rect(x + 2, y, 12, 7, leafDark);
    c.rect(x + 3, y, 10, 6, leaf);
    c.rect(x + 6, y + 7, 4, 8, bark);
    c.rect(x + 5, y + 14, 6, 2, shade(bark, 0.7));
  });
  t.set(HB.rock, (c, x, y) => {
    c.rect(x + 2, y + 5, 12, 10, stone.edge);
    c.paint(x + 3, y + 6, 10, 8, (px, py) => texel(stone, px, py));
  });
  t.set(HB.fence, (c, x, y) => {
    c.rect(x, y + 9, TS, 2, wood.base);
    c.rect(x, y + 13, TS, 2, wood.base);
    c.rect(x + 1, y + 7, 2, 9, wood.edge);
    c.rect(x + 13, y + 7, 2, 9, wood.edge);
  });
  t.set(HB.gate, (c, x, y) => {
    c.rect(x, y + 3, TS, 13, wood.edge);
    for (let i = 0; i < 4; i++) c.rect(x + 1 + i * 4, y + 4, 2, 12, wood.base);
    c.rect(x, y + 7, TS, 2, wood.dark);
    c.rect(x, y + 12, TS, 2, wood.dark);
  });
  t.set(HB.caveMouth, (c, x, y) => {
    c.paint(x, y, TS, TS, (px, py) => texel(stone, px, py));
    c.rect(x + 3, y + 3, 10, 13, rgb("#141010"));
    c.rect(x + 4, y + 2, 8, 1, rgb("#141010"));
  });
  t.set(HB.cliff, (c, x, y) => {
    c.paint(x, y, TS, TS, (px, py) => texel(stone, px, py));
    c.rect(x, y + TS - 2, TS, 2, stone.edge);
  });
  t.set(HB.flowers, (c, x, y) => {
    for (const [fx, fy, col] of [[3, 4, "#f0e040"], [10, 3, "#f06080"], [6, 10, "#ffffff"], [12, 11, "#f0e040"]] as const) {
      c.rect(x + fx, y + fy, 2, 2, rgb(col));
      c.set(x + fx, y + fy + 2, leafDark);
    }
  });
  t.set(HB.pot, (c, x, y) => {
    c.rect(x + 4, y + 5, 8, 10, rgb("#6a3a20"));
    c.rect(x + 5, y + 6, 6, 8, rgb("#b0602a"));
    c.rect(x + 5, y + 4, 6, 2, rgb("#6a3a20"));
  });
  t.set(HB.barrel, (c, x, y) => {
    c.rect(x + 3, y + 3, 10, 12, wood.edge);
    c.paint(x + 4, y + 4, 8, 10, (px, py) => texel(wood, py, px));
    c.rect(x + 3, y + 6, 10, 1, rgb("#505050"));
    c.rect(x + 3, y + 11, 10, 1, rgb("#505050"));
  });
  t.set(HB.sign, (c, x, y) => {
    c.rect(x + 7, y + 8, 2, 8, wood.edge);
    c.rect(x + 2, y + 2, 12, 7, wood.edge);
    c.rect(x + 3, y + 3, 10, 5, wood.light);
    c.rect(x + 4, y + 5, 8, 1, wood.edge);
  });
  t.set(HB.bookshelf, (c, x, y) => {
    c.rect(x, y, TS, TS, wood.edge);
    for (let r = 0; r < 3; r++) {
      c.rect(x + 1, y + 1 + r * 5, 14, 4, shade(wood.base, 0.5));
      for (let b = 0; b < 6; b++) c.rect(x + 2 + b * 2, y + 2 + r * 5, 1, 3, hsl((b * 70 + r * 40) % 360, 50, 45));
    }
  });
  t.set(HB.crate, (c, x, y) => {
    c.rect(x + 2, y + 3, 12, 12, wood.edge);
    c.paint(x + 3, y + 4, 10, 10, (px, py) => texel(wood, px, py));
    c.rect(x + 3, y + 8, 10, 1, wood.edge);
  });
  t.set(HB.bones, (c, x, y) => {
    c.rect(x + 3, y + 9, 8, 2, rgb("#e8e0d0"));
    c.rect(x + 2, y + 8, 2, 4, rgb("#e8e0d0"));
    c.rect(x + 10, y + 8, 2, 4, rgb("#e8e0d0"));
    c.rect(x + 8, y + 4, 3, 3, rgb("#e8e0d0"));
  });
  t.set(HB.stalagmite, (c, x, y) => {
    for (let r = 0; r < 12; r++) {
      const half = 1 + Math.floor(r / 2);
      c.rect(x + 8 - half, y + 3 + r, half * 2, 1, r === 11 ? stone.edge : stone.base);
    }
  });
  t.set(HB.crystal, (c, x, y) => {
    for (let r = 0; r < 10; r++) {
      const half = r < 5 ? 1 + r : 10 - r;
      c.rect(x + 8 - half, y + 3 + r, half * 2, 1, r < 5 ? rgb("#a0e8f0") : rgb("#50a0c0"));
    }
  });
  t.set(HB.window, (c, x, y) => {
    c.rect(x + 3, y + 3, 10, 9, wood.edge);
    c.rect(x + 4, y + 4, 8, 7, rgb("#a0d0f0"));
    c.rect(x + 7, y + 4, 1, 7, wood.edge);
    c.rect(x + 4, y + 7, 8, 1, wood.edge);
  });
  return t;
}

/** A standard 16-column IconSet with only the fixture database's cells
 * occupied. Each motif is original integer-pixel art; the importer halves
 * the 32 px source cells to the kit's 16 px item sprites. */
function fixtureIconSet(): Canvas {
  const c = new Canvas(16 * 32, 13 * 32);
  const at = (index: number): [number, number] => [(index % 16) * 32, Math.floor(index / 16) * 32];
  const tile = (index: number, base: ReturnType<typeof rgb>, accent: ReturnType<typeof rgb>): [number, number] => {
    const [x, y] = at(index);
    c.rect(x + 6, y + 6, 20, 20, shade(base, 0.45));
    c.rect(x + 8, y + 8, 16, 16, base);
    c.frame(x + 8, y + 8, 16, 16, accent);
    return [x, y];
  };

  // State and skill marks (not imported as inventory, but keep every
  // referenced database icon visibly self-contained).
  let [x, y] = tile(1, rgb("#8050b0"), rgb("#e0c8ff"));
  c.rect(x + 14, y + 10, 4, 12, rgb("#fff0a0"));
  c.rect(x + 10, y + 14, 12, 4, rgb("#fff0a0"));
  [x, y] = tile(76, rgb("#d07030"), rgb("#ffe0a0"));
  c.rect(x + 14, y + 9, 4, 14, rgb("#fff8d0"));
  c.rect(x + 10, y + 13, 12, 6, rgb("#fff8d0"));

  // Staff, sword and vest.
  [x, y] = tile(97, rgb("#704828"), rgb("#e0b060"));
  for (let p = 0; p < 16; p += 2) c.rect(x + 8 + p, y + 22 - p, 4, 4, rgb("#e0b060"));
  c.rect(x + 18, y + 8, 6, 6, rgb("#70d090"));
  [x, y] = tile(98, rgb("#405070"), rgb("#d8e8ff"));
  for (let p = 0; p < 14; p += 2) c.rect(x + 10 + p, y + 20 - p, 4, 4, rgb("#f0f4ff"));
  c.rect(x + 8, y + 20, 10, 4, rgb("#d0a040"));
  [x, y] = tile(135, rgb("#506080"), rgb("#d0d8e8"));
  c.rect(x + 10, y + 9, 12, 5, rgb("#d0d8e8"));
  c.rect(x + 8, y + 13, 16, 11, rgb("#a8b8d0"));
  c.rect(x + 14, y + 13, 4, 11, rgb("#506080"));

  // Potion and cave-pass/ticket.
  [x, y] = tile(176, rgb("#803050"), rgb("#ffc0d0"));
  c.rect(x + 13, y + 8, 6, 5, rgb("#e8d8c0"));
  c.rect(x + 10, y + 13, 12, 11, rgb("#e05070"));
  c.rect(x + 12, y + 15, 8, 4, rgb("#ff90b0"));
  [x, y] = tile(195, rgb("#806020"), rgb("#ffe080"));
  c.rect(x + 8, y + 11, 16, 10, rgb("#f0c858"));
  c.frame(x + 8, y + 11, 16, 10, rgb("#fff0a0"));
  c.rect(x + 15, y + 11, 2, 10, rgb("#806020"));
  return c;
}

