function hollowVillage(): RmMap {
  const g = new Grid(24, 16);
  g.fill(0, 0, 0, 23, 15, auto(K.grass));
  // Dirt: the plaza, the lane to the house door, the road east and the
  // path north through the gate to the cave mouth.
  g.fill(0, 10, 8, 12, 10, auto(K.dirt));
  g.fill(0, 11, 6, 11, 7, auto(K.dirt));
  g.fill(0, 13, 10, 19, 10, auto(K.dirt));
  g.fill(0, 19, 0, 19, 9, auto(K.dirt));
  // Pond (animated A1), an irregular blob.
  g.fill(0, 2, 10, 5, 13, auto(K.pond));
  g.set(0, 2, 10, auto(K.grass));
  g.set(0, 5, 13, auto(K.grass));
  g.fill(5, 2, 10, 5, 13, 1);
  g.set(5, 2, 10, 0);
  g.set(5, 5, 13, 0);
  // Tall grass (bush flag, terrain tag 1).
  g.fill(0, 20, 12, 22, 14, auto(K.tallGrass));
  // House: A3 roof over A3 wall; the door is an event at (11, 5).
  g.fill(0, 9, 2, 13, 3, auto(K.roof));
  g.fill(0, 9, 4, 13, 5, auto(K.wall));
  g.points(2, HB.window, [[10, 4], [12, 4]]);
  g.fill(4, 14, 2, 14, 5, 0b0101); // shadow on the left quarters east of the house
  // North enclosure: cliff with the cave mouth, a tree wall on the west,
  // a fence (blocks the tile's bottom edge only) with the gate at x 19.
  for (let x = 16; x <= 23; x++) if (x !== 19) g.set(2, x, 0, HB.cliff);
  g.set(2, 19, 0, HB.caveMouth);
  for (let y = 1; y <= 6; y++) g.set(2, 15, y, HB.treeTrunk);
  for (let y = 0; y <= 5; y++) g.set(3, 15, y, HB.treeTop);
  for (const x of [16, 17, 18, 20, 21, 22, 23]) g.set(2, x, 6, HB.fence);
  // Free-standing trees: trunk on z 2, star-flagged top on z 3 above it.
  for (const [x, y] of [[6, 5], [3, 7], [22, 8]] as const) {
    g.set(2, x, y, HB.treeTrunk);
    g.set(3, x, y - 1, HB.treeTop);
  }
  g.points(2, HB.rock, [[8, 13], [16, 12]]);
  g.points(2, HB.flowers, [[7, 8], [8, 11], [14, 13]]);
  g.set(2, 8, 7, HB.sign);

  const elderPage1 = page({
    image: { characterName: "People", characterIndex: 1 },
    list: list(
      mzText("Elder", "Ah, \\N[1]. A golem has woken in the cave", "and the north gate is barred. Will you help?"),
      choices(
        ["I'll help", "Not now"],
        -2,
        0,
        [
          [
            setVar(V_QUEST, 1),
            cmd(122, V_LUCK, V_LUCK, 0, 2, 1, 6),
            setVar(V_BONUS, 10),
            cmd(122, V_BONUS, V_BONUS, 1, 1, V_LUCK),
            switchOn(S_QUEST),
            mzText(
              "Elder",
              "Bless you. Your luck today reads \\V[2].",
              "Take the \\C[2]Cave Pass\\C[0] from the chest in my",
              "house, and keep the 50\\G beside it.",
            ),
          ],
          [mzText("Elder", "Then rest a while. The golem will wait.")],
        ],
        [mzText("Elder", "Hm? Speak up, child.")],
      ),
      ifThen(ifVar(V_QUEST, 1, 1), [mzText("Elder", "My house is just north of the plaza.")]),
    ),
  });
  const elderPage2 = page({
    cond: whenSwitch(S_QUEST),
    image: { characterName: "People", characterIndex: 1 },
    list: list(
      ifThen(
        ifSwitch(S_BOSS_DOWN),
        [
          mzText("Elder", "The golem is dust! Hollow is safe, \\N[1].", "\\C[3]Thank you.\\C[0]"),
          switchOn(S_PEACE),
          setVar(V_QUEST, 3),
        ],
        [
          ifThen(
            ifItem(I_PASS),
            [mzText("Elder", "Show the pass to the guard by the north gate.")],
            [mzText("Elder", "The chest is in my house, north of the plaza.")],
          ),
        ],
      ),
    ),
  });

  const doorRoute = route(
    [mv(R.dirFixOff), mv(R.turnLeft), mv(R.wait, 3), mv(R.turnRight), mv(R.wait, 3), mv(R.turnUp), mv(R.dirFixOn)],
    false,
    false,
    true,
  );

  const guardPage2 = page({
    cond: whenItem(I_PASS),
    image: { characterName: "People", characterIndex: 3 },
    list: list(
      mzText("Guard", "The elder's pass! Very well."),
      ifThen(
        ifItem(I_PASS),
        [
          cmd(129, 2, 0, true),
          mzText("Guard", "Take \\N[2] along; the cave is no place to go alone.", "Want to call \\N[2] something else?"),
          choices(["Rename", "Keep"], 1, 1, [[cmd(303, 2, 8)], []]),
          switchOn(S_GATE),
          setRoute(0, route([mv(R.turnUp), mv(R.wait, 20), mv(R.turnDown)], false, true, true)),
          cmd(250, SE.gate),
          mzText("Guard", "The gate is open. Mind the golem, \\N[1]."),
          selfOn("A"),
        ],
        [mzText("Guard", "...You had it a moment ago?")],
      ),
    ),
  });

  const bellLoop = loop(
    cmd(230, 60),
    addVar(V_TICKS, 1),
    ifThen(ifVar(V_TICKS, 1, 5), [selfOn("B"), cmd(113)]),
  );

  const events = [
    event(1, "Intro", 0, 15, [
      page({
        trigger: 3,
        list: list(
          comment("Opening: rain, a plugin call and a script line.", "Runs once (self switch A)."),
          cmd(236, "rain", 3, 60, false),
          cmd(357, "HollowLog", "mark", "Mark Chapter", { chapter: "1", label: "Arrival" }),
          cmd(657, "Chapter = 1"),
          cmd(657, "Label = Arrival"),
          script("const tag = \"hollow-intro\";", "$gameTemp.hollowTag = tag;"),
          mzText("", "Rain drums on the roofs of Hollow."),
          cmd(230, 30),
          cmd(236, "none", 0, 60, false),
          selfOn("A"),
        ),
      }),
      page({ cond: whenSelf("A"), list: list() }),
    ]),
    event(2, "Elder", 13, 9, [elderPage1, elderPage2]),
    event(3, "House Door", 11, 5, [
      page({
        image: { characterName: "!Things", characterIndex: 1 },
        dirFix: true,
        trigger: 1,
        list: list(cmd(250, SE.door), setRoute(0, doorRoute), transfer(2, 6, 8, 8, 0)),
      }),
    ]),
    event(4, "Gate", 19, 6, [
      page({ image: { tileId: HB.gate }, list: list(mzText("", "The gate is barred from the inside.")) }),
      page({ cond: whenSwitch(S_GATE), priority: 0, list: list() }),
    ]),
    event(5, "Guard", 18, 7, [
      page({
        image: { characterName: "People", characterIndex: 3 },
        list: list(mzText("Guard", "Halt! Only holders of the \\C[2]Cave Pass\\C[0] may pass.")),
      }),
      guardPage2,
      page({
        cond: whenSelf("A"),
        image: { characterName: "People", characterIndex: 3 },
        list: list(mzText("Guard", "Beware the golem, \\N[1].")),
      }),
    ]),
    event(6, "To Cave", 19, 0, [
      page({
        trigger: 2,
        list: list(switchOn(S_IN_CAVE), cmd(250, SE.steps), transfer(3, 10, 13, 8, 1)),
      }),
    ]),
    event(7, "Villager", 3, 3, [
      page({
        image: { characterName: "People", characterIndex: 5 },
        moveType: 3,
        route: route(
          [mv(R.left), mv(R.left), mv(R.wait, 30), mv(R.right), mv(R.right), mv(R.wait, 30)],
          true,
          false,
          false,
        ),
        list: list(mzText("Villager", "Rain again. Good for the pond, at least.")),
      }),
    ]),
    // Event 8 was deleted; the array keeps a null there.
    event(9, "Bell", 0, 14, [
      page({ trigger: 4, list: list(bellLoop) }),
      page({ cond: whenSelf("B"), list: list() }),
    ]),
  ];

  return rmMap({
    displayName: "Hollow",
    tilesetId: 1,
    grid: g,
    events,
    bgm: audio("hollow-theme", 70),
  });
}

function hollowHouse(): RmMap {
  const g = new Grid(13, 10);
  g.fill(0, 0, 0, 12, 9, auto(K.houseTop));
  g.fill(0, 1, 1, 11, 2, auto(K.houseSide));
  g.fill(0, 1, 3, 11, 8, a5(H5.wood));
  g.set(0, 6, 9, a5(H5.doormat));
  // The counter frames the shopkeeper, with a service opening at (9,5).
  // RPG Maker can trigger events across counter tiles, but that unrelated
  // interaction rule is intentionally reported as degraded by this importer.
  g.points(0, a5(H5.counter), [[8, 3], [8, 4], [8, 5], [10, 5], [11, 5]]);
  // A2 table with the table/counter flag.
  g.fill(0, 2, 6, 3, 7, auto(K.table));
  g.points(2, HB.window, [[3, 1], [9, 1]]);
  g.points(2, HB.bookshelf, [[1, 3], [2, 3]]);
  g.set(2, 11, 3, HB.crate);
  g.set(2, 11, 8, HB.pot);
  g.set(2, 1, 8, HB.barrel);

  const chestOpen = route(
    [mv(R.dirFixOff), mv(R.turnLeft), mv(R.wait, 3), mv(R.turnRight), mv(R.wait, 3), mv(R.turnUp), mv(R.dirFixOn)],
    false,
    false,
    true,
  );
  const events = [
    event(1, "Exit", 6, 9, [page({ trigger: 1, list: list(cmd(250, SE.door), transfer(1, 11, 6, 2, 0)) })]),
    event(2, "Chest", 6, 3, [
      page({
        image: { characterName: "!Things", characterIndex: 0 },
        dirFix: true,
        list: list(
          ifThen(
            ifSwitch(S_QUEST),
            [
              cmd(250, SE.chest),
              setRoute(0, chestOpen),
              cmd(126, I_POTION, 0, 0, 2),
              cmd(126, I_PASS, 0, 0, 1),
              cmd(125, 0, 0, 50),
              setVar(V_QUEST, 2),
              mzText("", "Found \\C[3]2 Potions\\C[0], the Cave Pass and 50\\G!"),
              cmd(117, 1),
              selfOn("A"),
            ],
            [mzText("", "The lid is stuck fast. Perhaps the elder knows.")],
          ),
        ),
      }),
      page({
        cond: whenSelf("A"),
        image: { characterName: "!Things", characterIndex: 0, direction: 8 },
        dirFix: true,
        list: list(mzText("", "Empty.")),
      }),
    ]),
    event(3, "Shopkeeper", 9, 4, [
      page({
        image: { characterName: "People", characterIndex: 2 },
        list: list(
          mzText("Shopkeeper", "Welcome! Potions, blades, a warm vest."),
          shop([[0, I_POTION, 0, 0], [1, 2, 1, 80], [2, 1, 0, 0]], false),
          mzText("Shopkeeper", "Come again!"),
        ),
      }),
    ]),
  ];
  return rmMap({ displayName: "Elder's House", tilesetId: 2, grid: g, events });
}

function hollowCave(): RmMap {
  const g = new Grid(20, 15);
  g.fill(0, 0, 0, 19, 14, auto(K.caveTop));
  g.fill(0, 1, 1, 18, 2, auto(K.caveSide));
  g.fill(0, 1, 3, 18, 13, a5(H5.caveFloor));
  g.set(0, 10, 14, a5(H5.caveFloor));
  // Waterfall down the north wall into a pool.
  g.fill(0, 3, 1, 4, 3, auto(K.waterfall));
  g.fill(0, 2, 4, 5, 5, auto(K.caveWater));
  g.points(2, HB.stalagmite, [[6, 8], [14, 6], [15, 11]]);
  g.set(2, 17, 3, HB.crystal);
  g.set(2, 12, 10, HB.bones);
  g.fill(5, 9, 3, 11, 5, 3);

  const events = [
    event(1, "Exit", 10, 14, [page({ trigger: 1, list: list(switchOff(S_IN_CAVE), transfer(1, 19, 1, 2, 2)) })]),
    // A counted goto loop (Label/Jump to Label) plus Get Location Info, Stop
    // SE, Select Item and the menu/save access flags: exercises the KRM3
    // command mappings with real MV parameter shapes.
    event(99, "Scout", 3, 13, [page({
      trigger: 0,
      list: list(
        cmd(134, 0), // Change Save Access: 0 disables
        cmd(135, 1), // Change Menu Access: nonzero enables
        cmd(122, 8, 0, 0, 0, 0), // v8 = 0
        cmd(118, "scout-loop"), // Label scout-loop
        cmd(122, 8, 8, 0, 1, 1), // v8 += 1
        cmd(285, 9, 0, 0, 3, 13), // v9 = terrain tag at (3,13), direct
        cmd(285, 10, 2, 0, 3, 13), // v10 = tile id on layer 1 at (3,13)
        cmd(104, 11, 1), // Select Item into v11, itypeId 1 (regular)
        cmd(251), // Stop SE
        ...ifThen(ifVar(8, 3, 3), [cmd(119, "scout-loop")]), // if v8 < 3 jump back
        cmd(135, 0), // Change Menu Access: 0 disables
        cmd(134, 1), // Change Save Access: nonzero enables
      ),
    })]),
    event(2, "Golem", 10, 4, [
      page({
        image: { characterName: "$Golem", characterIndex: 0 },
        list: list(
          mzText("Golem", "GRRR... who disturbs the deep?"),
          cmd(124, 0, 90),
          battle(
            1,
            [
              cmd(124, 1),
              switchOn(S_BOSS_DOWN),
              setVar(V_REWARD, 100),
              cmd(125, 0, 0, 100),
              mzText("", "The golem crumbles. You earn \\V[5]\\G."),
            ],
            [cmd(124, 1), addVar(V_ESCAPES, 1), mzText("", "You fled back into the dark.")],
            [cmd(124, 1), addVar(V_DEFEATS, 1), mzText("", "Beaten back... the golem still stands.")],
          ),
        ),
      }),
      page({ cond: whenSwitch(S_BOSS_DOWN), priority: 0, list: list() }),
    ]),
  ];
  return rmMap({ displayName: "Golem Cave", tilesetId: 2, grid: g, events, bgs: audio("hollow-cave", 60) });
}

