const STAGE = "stage-mv";
const MV_SCALE = 3;

const S_SCENE_DONE = 1;
const S_LEAD_BOWED = 2;
const S_SMOKE = 3;
const S_STAGEHAND = 4;
const V_CLAPS = 1;
const V_ENCORE = 2;

const SB = { chair: 1, lip: 2, stairs: 3, rail: 4, spotlight: 5, smoke: 6, curtain: 7, plant: 8, drum: 9 } as const;
const SK = { stage: 16, carpet: 17, aisle: 18, top: 80, side: 88 } as const;
const S5 = { void: 0, pit: 1 } as const;

const STAGE_SHEETS = ["", "Stage_A2", "", "Stage_A4", "Stage_A5", "Stage_B", "", "", ""];

const MV_SE = {
  overture: audio("stage-overture", 80),
  crowd: audio("stage-crowd", 50),
  fanfare: audio("stage-fanfare"),
  applause: audio("stage-applause"),
  clap: audio("stage-clap"),
  step: audio("stage-step", 70),
  puff: audio("stage-puff", 70),
};

function stageB(): Map<number, TileDraw> {
  const velvet = rgb("#a01a2a");
  const wood = material(rgb("#7a5030"), "planks", 500);
  const brass = rgb("#d0a040");
  const t = new Map<number, TileDraw>();
  t.set(SB.chair, (c, x, y) => {
    c.rect(x + 2, y + 1, 12, 9, shade(velvet, 0.5));
    c.rect(x + 3, y + 2, 10, 7, velvet);
    c.rect(x + 2, y + 10, 12, 4, shade(velvet, 0.75));
    c.rect(x + 3, y + 14, 2, 2, rgb("#202020"));
    c.rect(x + 11, y + 14, 2, 2, rgb("#202020"));
  });
  t.set(SB.lip, (c, x, y) => {
    c.paint(x, y, TS, 6, (px, py) => texel(wood, px, py));
    c.rect(x, y + 6, TS, 10, shade(wood.base, 0.45));
    c.rect(x, y + 6, TS, 1, brass);
  });
  t.set(SB.stairs, (c, x, y) => {
    for (let s = 0; s < 4; s++) {
      c.rect(x + 1, y + s * 4, 14, 3, shade(wood.base, 1 - s * 0.12));
      c.rect(x + 1, y + s * 4 + 3, 14, 1, wood.edge);
    }
  });
  t.set(SB.rail, (c, x, y) => {
    c.rect(x + 7, y, 2, TS, brass);
    c.rect(x + 6, y + 2, 4, 2, shade(brass, 0.7));
    c.rect(x + 6, y + 12, 4, 2, shade(brass, 0.7));
  });
  t.set(SB.spotlight, (c, x, y) => {
    c.rect(x + 3, y + 3, 10, 10, rgb("#f0e8a0", 140));
    c.rect(x + 5, y + 5, 6, 6, rgb("#fff8d0", 200));
  });
  t.set(SB.smoke, (c, x, y) => {
    for (const [cx, cy, r] of [[5, 9, 4], [10, 7, 5], [8, 12, 3]] as const) {
      c.rect(x + cx - r, y + cy - r + 1, r * 2, r * 2 - 2, rgb("#c8c8d0", 170));
      c.rect(x + cx - r + 1, y + cy - r, r * 2 - 2, r * 2, rgb("#c8c8d0", 170));
    }
  });
  t.set(SB.curtain, (c, x, y) => {
    c.paint(x, y, TS, TS, (px) => ((px & 3) === 0 ? shade(velvet, 0.6) : (px & 3) === 2 ? shade(velvet, 1.2) : velvet));
    c.rect(x, y, TS, 2, brass);
  });
  t.set(SB.plant, (c, x, y) => {
    c.rect(x + 4, y + 10, 8, 6, rgb("#7a4a2a"));
    c.rect(x + 3, y + 2, 10, 9, rgb("#2a6a2a"));
    c.rect(x + 5, y + 1, 6, 2, rgb("#3a8a3a"));
  });
  t.set(SB.drum, (c, x, y) => {
    c.rect(x + 2, y + 4, 12, 10, shade(velvet, 0.6));
    c.rect(x + 3, y + 5, 10, 8, rgb("#e8e0d0"));
    c.rect(x + 2, y + 8, 12, 1, brass);
  });
  return t;
}

/** Five original 192 px MV animation cells, authored at one-third scale
 * beside the rest of the MV fixture art. */
function stageSparkleSheet(): Canvas {
  const c = new Canvas(5 * 64, 64);
  const colors = ["#fff4a0", "#80e8ff", "#ff90d8", "#b0ff90", "#d0b0ff"];
  for (let cell = 0; cell < 5; cell++) {
    const ox = cell * 64;
    const color = rgb(colors[cell]!);
    const glow = rgb(colors[cell]!, 110);
    const radius = 8 + cell * 2;
    c.rect(ox + 32 - radius, 31, radius * 2 + 1, 3, glow);
    c.rect(ox + 31, 32 - radius, 3, radius * 2 + 1, glow);
    for (let d = 0; d <= radius; d++) {
      const half = Math.max(1, Math.floor((radius - d) / 4));
      c.rect(ox + 32 - half, 32 - d, half * 2 + 1, 1, color);
      c.rect(ox + 32 - half, 32 + d, half * 2 + 1, 1, color);
      c.rect(ox + 32 - d, 32 - half, 1, half * 2 + 1, color);
      c.rect(ox + 32 + d, 32 - half, 1, half * 2 + 1, color);
    }
    c.rect(ox + 29, 29, 7, 7, rgb("#ffffff"));
    c.rect(ox + 18 + cell * 2, 18, 3, 3, color);
    c.rect(ox + 43, 42 - cell, 2, 2, color);
  }
  return c;
}

function stageClouds(): Canvas {
  const c = new Canvas(128, 64);
  c.paint(0, 0, c.w, c.h, (_x, y) => shade(rgb("#203858"), 0.75 + y / 160));
  for (const [x, y, w] of [[4, 13, 26], [45, 31, 34], [92, 8, 26]] as const) {
    c.rect(x, y + 3, w, 6, rgb("#7890a8", 210));
    c.rect(x + 4, y, w - 10, 9, rgb("#98a8b8", 210));
  }
  for (const [x, y] of [[12, 5], [57, 10], [108, 27], [30, 43]] as const) c.rect(x, y, 2, 2, rgb("#fff0b0"));
  return c;
}

function stageGlow(): Canvas {
  const c = new Canvas(128, 64);
  c.paint(0, 0, c.w, c.h, (x, y) => {
    const band = Math.abs(x - 64) + Math.floor(Math.abs(y - 32) / 2);
    return band < 18 ? rgb("#705070") : band < 34 ? rgb("#403858") : rgb("#181c38");
  });
  for (const x of [16, 64, 112]) {
    c.rect(x - 5, 13, 10, 14, rgb("#d09040"));
    c.rect(x - 3, 15, 6, 10, rgb("#ffe090"));
    c.rect(x - 1, 4, 2, 9, rgb("#b08040"));
  }
  return c;
}

function stageArt(files: Files): void {
  const img = (path: string, canvas: Canvas) => files.set(`${STAGE}/img/${path}`, canvas.scaled(MV_SCALE).png());
  // IconSet cells are always 32 px in MV as well as MZ; unlike map,
  // character, animation, picture, and parallax art they do not scale with
  // the project's 48 px tile size.
  const systemImg = (path: string, canvas: Canvas) => files.set(`${STAGE}/img/${path}`, canvas.png());
  const a2 = (kind: number): Material => {
    switch (kind) {
      case SK.stage: return material(rgb("#9a6a38"), "planks", 516);
      case SK.carpet: return material(rgb("#7a2a3a"), "weave", 517);
      case SK.aisle: return material(rgb("#b0303a"), "speckle", 518);
      default: return hueMaterial(kind + 7, "speckle");
    }
  };
  const a4 = (kind: number): Material => {
    switch (kind) {
      case SK.top: return material(rgb("#3a2a24"), "planks", 580);
      case SK.side: return material(rgb("#5a4a6a"), "planks", 588);
      default: return hueMaterial(kind + 7, Math.floor(kind / 8) % 2 === 0 ? "speckle" : "bricks");
    }
  };
  img("tilesets/Stage_A2.png", sheetA2(a2));
  img("tilesets/Stage_A4.png", sheetA4(a4));
  img(
    "tilesets/Stage_A5.png",
    sheetA5((i) =>
      i === S5.void
        ? plainTile(material(rgb("#101010"), "plain", 0))
        : i === S5.pit
          ? plainTile(material(rgb("#4a3a2a"), "planks", 601))
          : plainTile(hueMaterial(i + 600, "checker")),
    ),
  );
  img("tilesets/Stage_B.png", sheetB(stageB()));
  img(
    "characters/Cast.png",
    characterSheet([
      person(look("#2a1a10", "#e0a030", "#3a3a6a")), // 0 Ivy
      person(look("#f0d060", "#c03040", "#2a2a2a")), // 1 lead
      person(look("#8a2a8a", "#f080c0", "#f080c0")), // 2 dancer
      person(look("#3a3a3a", "#404850", "#303030")), // 3 stagehand
      person(look("#c86a2a", "#40a0a0", "#3a4a6a")), // 4 fan
      person(look("#f0d060", "#f0f0f0", "#d0b040")), // 5 lead in costume
      person(look("#1a1a1a", "#2a2a2a", "#2a2a2a")), // 6 usher
      person(look("#9a9a9a", "#6a8a4a", "#3a3a3a")), // 7
    ]),
  );
  img("characters/$Moth.png", singleSheet(moth(rgb("#d8d0b0"), rgb("#5a4a3a"))));
  img("system/Balloon.png", balloonSheet());
  systemImg("system/IconSet.png", fixtureIconSet());
  img("animations/Sparkle.png", stageSparkleSheet());
  img("parallaxes/StageClouds.png", stageClouds());
  img("parallaxes/!StageGlow.png", stageGlow());
  // Full-screen curtain (816 x 624 once scaled).
  const curtain = new Canvas(272, 208);
  const velvet = rgb("#a01a2a");
  curtain.paint(0, 0, 272, 208, (x) => {
    const fold = x % 16;
    return fold < 2 ? shade(velvet, 0.55) : fold < 6 ? shade(velvet, 0.8) : fold < 11 ? velvet : shade(velvet, 1.18);
  });
  curtain.rect(0, 0, 272, 18, shade(velvet, 0.6));
  curtain.rect(0, 18, 272, 2, rgb("#d0a040"));
  for (let x = 0; x < 272; x += 4) curtain.rect(x, 196, 2, 12, rgb("#d0a040"));
  curtain.rect(0, 194, 272, 2, rgb("#d0a040"));
  img("pictures/Curtain.png", curtain);
}

function stageMap(): RmMap {
  const g = new Grid(17, 13);
  g.fill(0, 0, 0, 16, 12, auto(SK.top));
  g.fill(0, 1, 1, 15, 1, auto(SK.side));
  g.fill(0, 1, 2, 15, 6, auto(SK.stage));
  g.fill(0, 1, 7, 15, 11, auto(SK.carpet));
  g.fill(0, 7, 7, 9, 11, auto(SK.aisle));
  g.fill(0, 11, 7, 15, 8, a5(S5.pit));
  // Transparent backdrop windows prove the authored parallax is really
  // below the tile plane. Clear both RM ground layers. The lower window at
  // x=7,y=5 exposes the right lantern away from the map-name banner.
  g.fill(0, 3, 0, 5, 1, 0);
  g.fill(1, 3, 0, 5, 1, 0);
  g.set(0, 7, 5, 0);
  g.set(1, 7, 5, 0);
  g.fill(5, 1, 2, 15, 5, 1);
  g.fill(4, 1, 2, 1, 5, 0b0101);
  g.points(2, SB.curtain, [[1, 1], [2, 1], [14, 1], [15, 1]]);
  // Stairs at x 3 and x 8 only: the fan's pen (x 11..15) stays sealed.
  for (let x = 1; x <= 15; x++) g.set(2, x, 6, x === 3 || x === 8 ? SB.stairs : SB.lip);
  for (const y of [9, 11]) {
    for (let x = 1; x <= 6; x++) g.set(2, x, y, SB.chair);
    for (let x = 10; x <= 15; x++) g.set(2, x, y, SB.chair);
  }
  // The fan's pen: stage lip above, chairs below, a rail on the west.
  g.points(2, SB.rail, [[10, 7], [10, 8]]);
  g.set(2, 1, 7, SB.plant);
  g.set(2, 15, 2, SB.drum);

  const leadRoute = route(
    [
      mv(R.speed, 4),
      mv(R.freq, 5),
      mv(R.right),
      mv(R.right),
      mv(R.turnDown),
      mv(R.wait, 20),
      mv(R.left),
      mv(R.left),
      mv(R.left),
      mv(R.left),
      mv(R.dirFixOn),
      mv(R.right),
      mv(R.dirFixOff),
      mv(R.throughOn),
      mv(R.down),
      mv(R.up),
      mv(R.throughOff),
      mv(R.lowerL),
      mv(R.upperR),
      mv(R.jump, 1, 0),
      mv(R.forward),
      mv(R.toward),
      mv(R.random),
      mv(R.turnRandom),
      mv(R.turnToward),
      mv(R.turn180),
      mv(R.turn90R),
      mv(R.turn90L),
      mv(R.opacity, 160),
      mv(R.opacity, 255),
      mv(R.se, MV_SE.step),
      mv(R.image, "Cast", 5),
      mv(R.switchOn, S_LEAD_BOWED),
    ],
    false,
    true,
    true,
  );
  const playerRoute = route([mv(R.up), mv(R.up), mv(R.turnUp), mv(R.wait, 10)], false, false, true);

  const director = page({
    trigger: 3,
    list: list(
      comment("Opening cutscene. Runs once; self switch A hands control back."),
      cmd(211, 0),
      cmd(221),
      cmd(241, MV_SE.overture),
      cmd(245, MV_SE.crowd),
      cmd(231, 1, "Curtain", 0, 0, 0, 0, 100, 100, 255, 0),
      cmd(222),
      cmd(230, 30),
      mvText("Ladies and gentlemen, welcome to the", "\\C[6]Lantern Stage\\C[0]!"),
      cmd(246, 2),
      cmd(232, 1, 0, 0, 0, 0, -624, 100, 100, 255, 0, 60, true),
      cmd(235, 1),
      cmd(211, 1),
      cmd(284, "!StageGlow", false, false, 0, 0),
      cmd(356, "StageLights dim 50"),
      cmd(223, [-34, -34, 0, 34], 30, true),
      cmd(249, MV_SE.fanfare),
      cmd(224, [255, 255, 224, 170], 20, true),
      cmd(213, -1, 1, true),
      setRoute(-1, playerRoute),
      cmd(212, 2, 1, true),
      setRoute(2, leadRoute),
      cmd(203, 2, 0, 8, 3, 2),
      cmd(213, 2, 4, false),
      mvText("\\C[2]Lead:\\C[0] Thank you, thank you!", "Now, a little rhythm from the wings..."),
      switchOn(S_SMOKE),
      cmd(225, 5, 5, 30, true),
      switchOn(S_STAGEHAND),
      loop(ifThen(ifVar(V_CLAPS, 1, 3), [cmd(113)]), cmd(230, 10)),
      cmd(250, MV_SE.applause),
      cmd(213, 4, 3, false),
      cmd(223, [0, 0, 0, 0], 30, true),
      mvText("The show begins! Have a word with the usher."),
      switchOn(S_SCENE_DONE),
      selfOn("A"),
    ),
  });

  const stagehandWalk = route(
    [mv(R.walkOn), mv(R.right), mv(R.right), mv(R.wait, 10), mv(R.left), mv(R.left), mv(R.turnDown)],
    false,
    true,
    true,
  );

  const events = [
    event(1, "Director", 0, 12, [director, page({ cond: whenSelf("A"), list: list() })]),
    event(2, "Lead", 8, 3, [
      page({ image: { characterName: "Cast", characterIndex: 1 }, list: list(mvText("Break a leg!")) }),
      page({
        cond: whenSwitch(S_LEAD_BOWED),
        image: { characterName: "Cast", characterIndex: 5 },
        list: list(mvText("Did you catch my bow?")),
      }),
    ]),
    event(3, "Dancer", 4, 4, [
      page({
        image: { characterName: "Cast", characterIndex: 2 },
        moveType: 3,
        speed: 4,
        route: route(
          [
            mv(R.stepOn),
            mv(R.right),
            mv(R.lowerR),
            mv(R.upperL),
            mv(R.left),
            mv(R.turn180),
            mv(R.wait, 20),
            mv(R.turnAway),
            mv(R.wait, 20),
          ],
          true,
          false,
          false,
        ),
        list: list(mvText("One, two, three, four!")),
      }),
    ]),
    event(4, "Fan", 13, 8, [
      page({
        image: { characterName: "Cast", characterIndex: 4 },
        moveType: 1,
        freq: 4,
        list: list(mvTextAt(1, 0, "Woo! Front row!")),
      }),
    ]),
    event(5, "Stagehand", 12, 3, [
      page({ image: { characterName: "Cast", characterIndex: 3 }, list: list(mvText("Places, everyone!")) }),
      page({
        cond: whenSwitch(S_STAGEHAND),
        image: { characterName: "Cast", characterIndex: 3 },
        trigger: 4,
        list: list(
          setRoute(0, stagehandWalk),
          cmd(250, MV_SE.clap),
          addVar(V_CLAPS, 1),
          ifThen(ifVar(V_CLAPS, 1, 3), [switchOff(S_STAGEHAND)]),
        ),
      }),
    ]),
    event(6, "Moth", 2, 8, [
      page({
        image: { characterName: "$Moth", characterIndex: 0 },
        moveType: 2,
        freq: 5,
        priority: 2,
        through: true,
        stepAnime: true,
        list: list(),
      }),
    ]),
    event(7, "Smoke", 6, 5, [
      page({ list: list() }),
      page({
        cond: whenSwitch(S_SMOKE),
        image: { tileId: SB.smoke },
        priority: 2,
        trigger: 4,
        list: list(cmd(250, MV_SE.puff), cmd(230, 45), cmd(214)),
      }),
    ]),
    event(8, "Spotlight", 8, 5, [
      page({
        image: { tileId: SB.spotlight },
        priority: 0,
        list: list(mvTextAt(2, 1, "A chalk mark: the lead's spot.")),
      }),
    ]),
    event(9, "Usher", 14, 10, [
      page({
        image: { characterName: "Cast", characterIndex: 6, direction: 4 },
        list: list(mvText("The show starts soon. Find your seat!")),
      }),
      page({
        cond: { ...whenSwitch(S_SCENE_DONE), variableId: V_CLAPS, variableValid: true, variableValue: 3 },
        image: { characterName: "Cast", characterIndex: 6, direction: 4 },
        list: list(
          ifThen(
            ifVar(V_CLAPS, 0, 3),
            [mvText("Three claps exactly! Bravo, \\N[1]."), setVar(V_ENCORE, 1), cmd(213, 0, 4, false)],
            [mvText("\\V[1] claps? The stagehand lost count.")],
          ),
        ),
      }),
    ]),
  ];
  return rmMap({
    displayName: "Lantern Stage",
    tilesetId: 1,
    grid: g,
    events,
    parallax: { name: "StageClouds", loopX: true, loopY: false, sx: 2, sy: 0, show: true },
  });
}

