// =====================================================================================================

/** Build every fixture file in memory. Keys are paths relative to the
 *  fixtures directory. */
export function buildFixtures(): Files {
  const files: Files = new Map();
  hollowData(files);
  hollowArt(files);
  stageData(files);
  stageArt(files);
  return files;
}

/** Write both projects under `outRoot`; returns the relative paths written,
 *  sorted. */
export function generateFixtures(outRoot: string): string[] {
  const files = buildFixtures();
  const paths = [...files.keys()].sort();
  for (const rel of paths) {
    const path = join(outRoot, rel);
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, files.get(rel)!);
  }
  return paths;
}

if (import.meta.main) {
  const out = process.argv[2] ?? new URL(".", import.meta.url).pathname;
  const written = generateFixtures(out);
  console.log(`rpgmaker fixtures: wrote ${written.length} files under ${out}`);
}
